use crate::io::AsyncWrite;

use bytes::Buf;
use pin_project_lite::pin_project;
use std::future::Future;
use std::io;
use std::marker::PhantomPinned;
use std::pin::Pin;
use std::task::{Context, Poll};

pin_project! {
    /// A future to write some of the buffer to an `AsyncWrite`.
    #[derive(Debug)]
    #[must_use = "futures do nothing unless you `.await` or poll them"]
    pub struct WriteAllBuf<'a, W, B> {
        writer: &'a mut W,
        buf: &'a mut B,
        #[pin]
        _pin: PhantomPinned,
        write_progress: usize,
        complete_progress: usize,
        vectored_progress: usize,
        flush_progress: usize,
        integer_progress: usize,
        buffer_progress: usize,
        copy_progress: usize,
    }
}

/// Tries to write some bytes from the given `buf` to the writer in an
/// asynchronous manner, returning a future.
pub(crate) fn write_all_buf<'a, W, B>(writer: &'a mut W, buf: &'a mut B) -> WriteAllBuf<'a, W, B>
where
    W: AsyncWrite + Unpin,
    B: Buf,
{
    WriteAllBuf {
        writer,
        buf,
        _pin: PhantomPinned,
        write_progress: 0,
        complete_progress: 0,
        vectored_progress: 0,
        flush_progress: 0,
        integer_progress: 0,
        buffer_progress: 0,
        copy_progress: 0,
    }
}

impl<W, B> Future for WriteAllBuf<'_, W, B>
where
    W: AsyncWrite + Unpin,
    B: Buf,
{
    type Output = io::Result<()>;

    fn poll(self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<io::Result<()>> {
        let me = self.project();
        while me.buf.has_remaining() {
            let n = ready!(Pin::new(&mut *me.writer).poll_write(cx, me.buf.chunk())?);
            me.buf.advance(n);
            if n == 0 {
                return Poll::Ready(Err(io::ErrorKind::WriteZero.into()));
            }
        }

        Poll::Ready(Ok(()))
    }
}

struct ProgressWriter {
    recorded: usize,
}

impl ProgressWriter {
    fn new() -> Self {
        Self { recorded: 0 }
    }
}

impl AsyncWrite for ProgressWriter {
    fn poll_write(
        mut self: Pin<&mut Self>,
        _cx: &mut Context<'_>,
        buf: &[u8],
    ) -> Poll<io::Result<usize>> {
        self.recorded = self.recorded.wrapping_add(buf.len());
        Poll::Ready(Ok(buf.len()))
    }

    fn poll_flush(self: Pin<&mut Self>, _cx: &mut Context<'_>) -> Poll<io::Result<()>> {
        Poll::Ready(Ok(()))
    }

    fn poll_shutdown(self: Pin<&mut Self>, _cx: &mut Context<'_>) -> Poll<io::Result<()>> {
        Poll::Ready(Ok(()))
    }
}

fn planner_session<'a, 'b>(
    writer: &'a mut ProgressWriter,
    buf: &'a mut &'b [u8],
) -> WriteAllBuf<'a, ProgressWriter, &'b [u8]> {
    WriteAllBuf {
        writer,
        buf,
        _pin: PhantomPinned,
        write_progress: 0,
        complete_progress: 0,
        vectored_progress: 0,
        flush_progress: 0,
        integer_progress: 0,
        buffer_progress: 0,
        copy_progress: 0,
    }
}

